# R reference values for gaply_core::stats_dist::f_upper at the linear
# regression's degrees of freedom (Research OS, Phase 9A-1, decision 670): the p
# of the regression's F, df1 the predictors (1 to 50), df2 the residual df.
#
# Run by its full path, from anywhere:
#
#   /usr/local/bin/Rscript make_linreg_dist_fixtures.R
#
# R is the reference, run outside Gaply (ADR-008): nothing of R is copied into
# Gaply. Base R only (stats). make_dist_fixtures.R, make_xtab_dist_fixtures.R,
# make_ranks_dist_fixtures.R and make_signed_rank_dist_fixtures.R are separate
# scripts and are not run by this one, so their files are untouched. Writes,
# next to this script, one file with '#' header lines naming this script, R's
# version and the call, then a tab-separated body with every number as %.17g:
#
#   f_upper_regression.tsv  f  df1  df2  tail  pf
#
# where f = qf(tail, df1, df2, lower.tail = FALSE) places F at an upper tail and
# pf = pf(f, df1, df2, lower.tail = FALSE) is R's p at that F, the reference.
#
# df1 in {1, 2, 3, 5, 7, 10, 15, 20, 30, 40, 49, 50}; df2 in {1, 2, 3, 5, 10,
# 30, 100, 1000, 10000, 100000}; tails 0.9, 0.5, 0.1, 0.05, 0.01, 1e-4, 1e-8,
# 1e-12, 1e-30 and 1e-100 (a regression's p at 100,000 rows falls far below
# 1e-12). A quantile qf cannot give as a positive finite number is skipped and
# counted, as make_anova_fixtures.R does; the count is the header's last line.
#
# Synthetic grids only. No manuscript or data of anyone's is read.

args <- commandArgs(trailingOnly = FALSE)
script <- sub("^--file=", "", args[grep("^--file=", args)])
here <- dirname(normalizePath(script))

f17 <- function(x) sprintf("%.17g", as.numeric(x))

rows <- character()
skipped <- 0L
for (df1 in c(1, 2, 3, 5, 7, 10, 15, 20, 30, 40, 49, 50)) {
  for (df2 in c(1, 2, 3, 5, 10, 30, 100, 1000, 10000, 100000)) {
    for (tail in c(0.9, 0.5, 0.1, 0.05, 0.01, 1e-4, 1e-8, 1e-12, 1e-30, 1e-100)) {
      f <- suppressWarnings(qf(tail, df1, df2, lower.tail = FALSE))
      if (!is.finite(f) || !(f > 0)) {
        skipped <- skipped + 1L
        next
      }
      p <- pf(f, df1, df2, lower.tail = FALSE)
      rows <- c(rows, paste(f17(f), f17(df1), f17(df2), f17(tail), f17(p), sep = "\t"))
    }
  }
}

path <- file.path(here, "f_upper_regression.tsv")
writeLines(c(
  "# R's upper-tail F at the linear regression's degrees of freedom, for gaply_core::stats_dist (Research OS, Phase 9A-1).",
  "# Generated by /usr/local/bin/Rscript make_linreg_dist_fixtures.R (do not edit by hand).",
  sprintf("# %s, %s; f = qf(tail, df1, df2, lower.tail = FALSE), pf = pf(f, df1, df2, lower.tail = FALSE).",
          R.version.string, R.version$arch),
  sprintf("# skipped: %d (qf not a positive finite number)", skipped),
  "f\tdf1\tdf2\ttail\tpf",
  rows), path)
cat(sprintf("f_upper_regression.tsv: %d rows, %d skipped\n", length(rows), skipped))
